<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { onShow } from '@dcloudio/uni-app';
import PjIcon from '../../components/PjIcon.vue';
import { api, useApp, uuid } from '../../store';
const app=useApp();
const tab=ref('home'),modal=ref(''),busy=ref(false),booting=ref(true),bootError=ref(''),message=ref(''),error=ref('');
const selected=ref<any>(null),form=reactive<any>({}),invite=ref(''),history=ref<any[]>([]),filter=ref('ALL');
const pending=ref<any>(null),myApplications=ref<any[]>([]);
const d=computed(()=>app.data),admin=computed(()=>!!d.value?.admin);
const roleLabel=(r:string)=>({OWNER:'群主',ADMIN:'管理员',MEMBER:'成员'}[r]||'成员');
const tabs=[{id:'home',icon:'home',label:'群组首页'},{id:'daily',icon:'check',label:'日常'},{id:'activities',icon:'list',label:'活动'},{id:'rewards',icon:'gift',label:'奖励商店'},{id:'mine',icon:'user',label:'我的成长'}];
const homeTools=[{id:'members',label:'成员管理',icon:'users',color:'green',hint:'成员与积分'},{id:'reviewDaily',label:'日常审核',icon:'check',color:'blue',hint:'每日完成情况'},{id:'reviewActivities',label:'活动审核',icon:'list',color:'purple',hint:'参与与审核'},{id:'orders',label:'兑换管理',icon:'scan',color:'peach',hint:'订单与核销'}];
const adminTabs=[...homeTools,{id:'activity',icon:'list',label:'操作记录'}];
const editTools=[{id:'manageDaily',icon:'check',label:'日常管理'},{id:'manageActivities',icon:'list',label:'活动管理'},{id:'manageRewards',icon:'gift',label:'奖励管理'}];
const titles:any={daily:'日常',manageDaily:'日常管理',manageActivities:'活动管理',activities:'活动',home:'群组首页',rewards:'奖励商店',mine:'我的成长',members:'成员管理',manageRewards:'奖励管理',orders:'兑换管理',activity:'操作记录'};
const activeRewards=computed(()=>(d.value?.rewards||[]).filter((r:any)=>r.status==='ACTIVE'&&(filter.value==='ALL'||r.type===filter.value)));
const myOrders=computed(()=>(d.value?.orders||[]).filter((o:any)=>o.memberId===d.value?.membership.id));
const pendingOrders=computed(()=>(d.value?.orders||[]).filter((o:any)=>o.status==='PENDING'));
const availableMembers=computed(()=>(d.value?.members||[]).filter((m:any)=>m.id!==d.value?.membership.id));
const income=computed(()=>(d.value?.entries||[]).filter((e:any)=>e.delta>0).reduce((s:number,e:any)=>s+e.delta,0));
const fmt=(n:number)=>new Intl.NumberFormat('en-US').format(n||0);
const date=(v:string)=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const orderName=(s:string)=>({PENDING:'待领取',FULFILLED:'已完成',CANCELED:'已取消'}[s]||s);
const rewardStatus=(s:string)=>({DRAFT:'草稿',ACTIVE:'已上架',INACTIVE:'已下架'}[s]);
const auditName=(s:string)=>({ACTIVITY_PUBLISH:'发布活动',ACTIVITY_CLOSE:'停止活动领取',ACTIVITY_CLAIM:'参与活动',ACTIVITY_SUBMIT:'提交完成',ACTIVITY_APPROVE:'活动审核通过',ACTIVITY_REJECT:'活动驳回',GRANT:'发放积分',ADJUSTMENT:'调整积分',REVERSAL:'冲正积分',REWARD_CREATE:'新建奖励',REWARD_EDIT:'编辑奖励',REWARD_STATUS:'调整上架状态',STOCK_ADJUST:'调整库存',ROLE_CHANGE:'修改成员角色',OWNER_TRANSFER:'转让群主',APPROVED:'同意入群',REJECTED:'拒绝入群',cancel:'取消兑换',fulfill:'核销奖励'}[s]||s);
const modalTitle=computed(()=>({groups:'我的群组',create:'创建一个新群组',join:'加入群组',invite:'邀请伙伴加入',grant:'让努力获得积分',reward:'兑换这份小美好',order:'兑换详情',newReward:'添加奖励',editReward:'编辑奖励',stock:'调整奖励库存',member:'成员详情',settings:'群组设置',recovery:'确认上次操作',users:'切换体验账号',profile:'个人资料',newActivity:form.kind==='DAILY'?'发布日常':'发布活动',taskSubmit:'提交完成',taskReview:'审核活动'}[modal.value]||''));
const activityState=(s:string)=>({CLAIMED:'进行中',SUBMITTED:'待审核',REJECTED:'需修改',APPROVED:'已获积分'}[s]||'未领取');
const reviewClaims=computed(()=>(d.value?.activityClaims||[]).filter((c:any)=>c.status==='SUBMITTED'));
const managingActivities=computed(()=>['manageDaily','manageActivities'].includes(tab.value));
const activityKind=computed(()=>['daily','manageDaily'].includes(tab.value)?'DAILY':'LIMITED');
const visibleActivities=computed(()=>{const items=d.value?.activities||[];return items.filter((a:any)=>a.kind===activityKind.value);});
function activityAvailable(t:any){const now=Date.now();return t.status==='ACTIVE'&&(t.kind==='DAILY'||(now>=Date.parse(t.startsAt)&&now<Date.parse(t.endsAt)));}
function activityPhase(t:any){return t.status==='CLOSED'?'已停止参与':t.kind==='DAILY'?'每日可参与一次':Date.now()<Date.parse(t.startsAt)?'未开始':Date.now()>=Date.parse(t.endsAt)?'已结束':'进行中';}
function periodField(field:string,e:any){form[field]=e.detail.value;}
const myClaim=(tid:string)=>d.value?.activityClaims?.find((c:any)=>c.activityId===tid&&c.memberId===d.value.membership.id&&(c.period==='ONCE'||c.period===d.value.activityDate));
const activityTitle=(tid:string)=>d.value?.activities?.find((t:any)=>t.id===tid)?.title||'成长活动';
function toast(t:string){message.value=t;setTimeout(()=>message.value='',3500);}
function openHistory(){if(busy.value||pending.value)return;uni.navigateTo({url:'/pages/activity-history/index?groupId='+app.gid+'&kind='+(tab.value==='daily'?'DAILY':'LIMITED')});}
function openProgress(kind:string){if(busy.value||pending.value)return;uni.navigateTo({url:'/pages/activity-progress/index?groupId='+app.gid+'&kind='+kind});}
function nav(t:string){if(busy.value||pending.value){toast('请先确认当前操作结果');return;}if(t==='reviewDaily'||t==='reviewActivities'){openProgress(t==='reviewDaily'?'DAILY':'LIMITED');return;}tab.value=t;filter.value='ALL';if(['daily','activities','manageDaily','manageActivities'].includes(t))app.refresh();}
function open(name:string,item?:any){if(busy.value||pending.value){toast('请先确认当前操作结果');return;}error.value='';selected.value=item||null;Object.keys(form).forEach(k=>delete form[k]);invite.value='';history.value=[];
 if(name==='newActivity')Object.assign(form,{title:'',description:'',points:10,kind:activityKind.value,startDate:d.value?.activityDate,endDate:d.value?.activityDate,startTime:'00:00',endTime:'23:59'});
 if(name==='taskSubmit')Object.assign(form,{submission:item.submission||''});
 if(name==='taskReview')Object.assign(form,{decision:'APPROVE',reason:''});
 if(name==='profile')Object.assign(form,{displayName:app.user.displayName});
 if(name==='grant')Object.assign(form,{memberId:item?.id||availableMembers.value[0]?.id||'',delta:10,reason:'',type:'GRANT'});
 if(name==='newReward')Object.assign(form,{name:'',description:'',type:'VIRTUAL',art:'gift',costPoints:30,initialStock:10,fulfillmentInstructions:'向管理员确认后领取'});
 if(name==='editReward')Object.assign(form,{name:item.name,description:item.description,costPoints:item.costPoints,fulfillmentInstructions:item.fulfillmentInstructions});
 if(name==='stock')Object.assign(form,{delta:10,reason:''});
 if(name==='create')Object.assign(form,{name:'',description:'',color:'blue'});
 if(name==='settings')Object.assign(form,{name:d.value.group.name,description:d.value.group.description});
 modal.value=name;
 if(name==='groups')api('/groups').then(r=>app.groups=r.items).catch(e=>error.value=e.message);
 if(name==='member')api(`/groups/${app.gid}/members/${item.id}/ledger`).then(r=>history.value=r.items).catch(e=>error.value=e.message);
 if(name==='join')api('/me/join-applications').then(r=>myApplications.value=r.items).catch(()=>{});
}
function close(){if(busy.value||pending.value){toast('操作结果尚未确认，请重试确认');return;}modal.value='';error.value='';}
async function switchGroup(gid:string){if(busy.value||pending.value)return;modal.value='';tab.value='home';await app.switchGroup(gid);}
async function login(user:any){if(busy.value||pending.value)return;const saved=uni.getStorageSync('pj-pending');if(saved&&saved.userId!==user.id){error.value='请先选择上次操作的账号，确认待处理结果';return;}busy.value=true;error.value='';try{await app.login(user);tab.value='home';if(saved){pending.value=saved;if(saved.groupId&&app.gid!==saved.groupId)await app.switchGroup(saved.groupId);modal.value='recovery';}else{modal.value=app.gid?'':'groups';}}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function loginWechat(){if(busy.value)return;busy.value=true;error.value='';try{await app.loginWechat();tab.value='home';const saved=uni.getStorageSync('pj-pending');if(saved){pending.value=saved;if(saved.groupId&&app.gid!==saved.groupId)await app.switchGroup(saved.groupId);modal.value='recovery';}else modal.value=app.gid?'':'groups';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function perform(path:string,body:any,success='操作已完成',method='POST'){
 if(busy.value)return;error.value='';const signature=JSON.stringify({path,body,method});
 if(pending.value&&pending.value.signature!==signature){error.value='请先重试确认上次操作';return;}
 const p=pending.value||{path,body,method,key:uuid(),signature,userId:app.user.id,groupId:app.gid,success};pending.value=p;uni.setStorageSync('pj-pending',p);busy.value=true;
 try{const result=await api(path,method,body,p.key);pending.value=null;uni.removeStorageSync('pj-pending');if(path.endsWith('/invitations')){invite.value=result.code;}else{modal.value='';toast(success);}
 if(path==='/me'||path==='/me/avatar'){app.user=result;await app.refresh();if(path==='/me/avatar'){modal.value='profile';}return result;}
 if(path==='/groups')await app.loadGroups(result.group.id);else if(path==='/join-applications'){await app.loadGroups();}else{await app.refresh();}
 if(path.endsWith('/redemptions')&&result.order){selected.value=app.data?.orders.find((o:any)=>o.id===result.order.id)||{...result.order,memberName:app.user.displayName};Object.keys(form).forEach(k=>delete form[k]);modal.value='order';}
 if(!app.gid&&!modal.value)modal.value='groups';return result;
 }catch(e:any){error.value=e.message;if(!e.uncertain&&e.status<500){pending.value=null;uni.removeStorageSync('pj-pending');}else{error.value+='。请点击重试确认，不要重复提交新操作。';}}
 finally{busy.value=false;}
}
function nicknameChanged(e:any){form.displayName=e.detail.value;}
async function chooseAvatar(e:any){if(busy.value||pending.value)return;error.value='';try{const imageBase64:string=await new Promise((resolve,reject)=>uni.getFileSystemManager().readFile({filePath:e.detail.avatarUrl,encoding:'base64',success:r=>resolve(String(r.data)),fail:()=>reject(new Error('头像读取失败，请重新选择'))}));if(imageBase64.length>2800000)throw new Error('请选择不超过 2 MB 的头像');await perform('/me/avatar',{imageBase64},'头像已更新');}catch(e:any){error.value=e.message;}}
async function submit(){
 if(modal.value==='profile')return perform('/me',{displayName:String(form.displayName||'').trim()},'昵称已保存','PATCH');
 const base='/groups/'+app.gid;
 if(modal.value==='newActivity')return perform(base+(form.kind==='DAILY'?'/routines':'/events'),{title:form.title,description:form.description,points:Number(form.points),...(form.kind==='LIMITED'?{startsAt:form.startDate+'T'+form.startTime+':00+08:00',endsAt:form.endDate+'T'+form.endTime+':00+08:00'}:{})},form.kind==='DAILY'?'日常已发布':'活动已发布');
 if(modal.value==='taskSubmit')return perform(base+(selected.value.kind==='DAILY'?'/daily-entries/':'/event-entries/')+selected.value.id+'/submit',{submission:form.submission,expectedVersion:selected.value.version},'已提交，等待管理员审核');
 if(modal.value==='taskReview')return confirmAction(form.decision==='APPROVE'?'通过并发放积分？':'驳回活动？',form.decision==='APPROVE'?'审核通过后，活动积分将自动计入该成员账户。':'成员可以根据原因修改后重新提交。',()=>perform(base+(selected.value.kind==='DAILY'?'/daily-entries/':'/event-entries/')+selected.value.id+'/review',{decision:form.decision,reason:form.reason,expectedVersion:selected.value.version},form.decision==='APPROVE'?'审核通过，积分已到账':'已驳回，请成员修改'));
 if(modal.value==='create')return perform('/groups',{name:form.name,description:form.description,color:form.color},'新群组已创建');
 if(modal.value==='join')return perform('/join-applications',{code:form.code||''},'加入申请已发送，等待管理员审核');
 if(modal.value==='invite')return perform(base+'/invitations',{},'邀请码已生成');
 if(modal.value==='grant')return perform(base+'/point-entries',{memberId:form.memberId,type:form.type,delta:Number(form.delta),reason:form.reason},'积分已记入成员账户');
 if(modal.value==='reward')return perform(base+'/redemptions',{rewardId:selected.value.id,expectedRewardVersion:selected.value.version,expectedCostPoints:selected.value.costPoints},'兑换成功！可以去领取奖励了');
 if(modal.value==='newReward')return perform(base+'/rewards',{...form,costPoints:Number(form.costPoints),initialStock:Number(form.initialStock)},'奖励草稿已保存，请在奖励管理中上架');
 if(modal.value==='editReward')return perform(base+'/rewards/'+selected.value.id,{...form,costPoints:Number(form.costPoints),expectedVersion:selected.value.version},'奖励已更新','PATCH');
 if(modal.value==='stock')return perform(base+'/rewards/'+selected.value.id+'/stock-adjustments',{delta:Number(form.delta),reason:form.reason,expectedStockVersion:selected.value.stockVersion},'库存已更新');
 if(modal.value==='settings')return perform(base,{name:form.name,description:form.description,expectedVersion:d.value.group.version},'群组资料已更新','PATCH');
}
async function confirmAction(title:string,content:string,fn:()=>any){uni.showModal({title,content,confirmText:'确认',confirmColor:'#3564ed',success:r=>{if(r.confirm)fn();}});}
function orderAction(action:string){const o=selected.value;const why=String(form.reason||'').trim();if(!why){error.value=action==='cancel'?'请填写取消原因':'请填写已交付的内容';return;}confirmAction(action==='cancel'?'确认取消兑换？':'确认已交付奖励？',action==='cancel'?`将退还 ${o.costPoints} 积分，并恢复库存。`:'确认后订单完成，请先将奖励交付给成员。',()=>perform(`/groups/${app.gid}/redemptions/${o.id}/${action}`,{reason:why},action==='cancel'?'已取消，积分已返还':'奖励核销成功'));}
function toggleReward(r:any){confirmAction(r.status==='ACTIVE'?'下架这份奖励？':'上架这份奖励？',r.status==='ACTIVE'?'已有订单仍然可以领取。':'成员可以使用积分兑换这份奖励。',()=>perform(`/groups/${app.gid}/rewards/${r.id}/status`,{status:r.status==='ACTIVE'?'INACTIVE':'ACTIVE',expectedVersion:r.version},'奖励状态已更新'));}
function decision(a:any,decision:string){perform(`/groups/${app.gid}/join-applications/${a.id}/decision`,{decision},decision==='APPROVE'?'新伙伴已加入群组':'已拒绝申请');}
function changeRole(){const m=selected.value;confirmAction(m.role==='ADMIN'?'撤销管理员？':'设为管理员？','权限只在当前群组内生效。',()=>perform(`/groups/${app.gid}/members/${m.id}/role`,{role:m.role==='ADMIN'?'MEMBER':'ADMIN',expectedVersion:m.version},'成员角色已更新','PATCH'));}
function transfer(){const m=selected.value;confirmAction('转让群主？',`将「${d.value.group.name}」转让给 ${m.displayName}，你将成为管理员。`,()=>perform(`/groups/${app.gid}/ownership-transfer`,{newOwnerMemberId:m.id,expectedVersion:d.value.group.version},'群主已转让'));}
function reverse(e:any){confirmAction('冲正这笔积分？',`将为 ${selected.value.displayName} ${e.delta>0?'扣回':'返还'} ${Math.abs(e.delta)} 积分，原流水仍保留。`,()=>perform(`/groups/${app.gid}/point-entries/${e.id}/reversal`,{reason:'管理员纠正原积分记录'},'冲正成功'));}
function copyInvite(){uni.setClipboardData({data:invite.value,success:()=>toast('邀请码已复制')});}
async function boot(){booting.value=true;bootError.value='';try{await app.init();pending.value=app.user?(uni.getStorageSync('pj-pending')||null):null;if(pending.value&&app.user?.id===pending.value.userId){if(app.gid!==pending.value.groupId&&pending.value.groupId)await app.switchGroup(pending.value.groupId);modal.value='recovery';}else if(app.user&&!app.gid)modal.value='groups';}catch(e:any){bootError.value=e.message;}finally{booting.value=false;}}
onMounted(boot);
onShow(()=>{if(!booting.value&&app.user&&app.gid)app.refresh();});
</script>

<template>
 <view v-if="booting" class="boot"><view class="spinner"/><text>正在打开积乐圈…</text></view>
 <view v-else-if="bootError" class="boot"><text>{{bootError}}</text><button role="button" class="btn primary" @click="boot">重新连接</button></view>
 <view v-else-if="!app.user" class="login-page">
  <view class="login-story"><view class="brand"><image src="/static/pointjoy.png" class="logo"/><view><text class="brand-name">积乐圈</text><text class="brand-en">POINTJOY</text></view></view><view class="login-copy"><text class="eyebrow">SMALL STEPS. REAL JOY.</text><text class="login-title">每一份努力，<br/>都有回响。</text><text class="login-desc">与伙伴一起积攒成长，<br/>把点滴进步，换成喜欢的生活。</text><view class="login-art"><image src="/static/gift.svg" mode="aspectFit"/></view></view><text class="login-footer">积乐圈 · 让每一份努力，都有奖励</text></view>
  <view v-if="app.authMode==='demo'" class="login-panel"><view class="pill">本地体验版</view><text class="section-title">从一个身份，开始体验</text><text class="muted intro">选择演示账号，体验群组、积分和奖励的完整流程。</text><button role="button" v-for="u in app.users" :key="u.id" class="identity" :disabled="busy" @click="login(u)"><view class="avatar" :class="u.avatar"><image v-if="u.avatar?.startsWith('http')" class="avatar-image" :src="u.avatar" mode="aspectFill"/><text v-else>{{u.displayName.slice(-2)}}</text></view><view class="identity-copy"><text class="strong">{{u.displayName}}</text><text class="small muted">{{u.displayName==='林小满'?'推荐体验 · 拥有多个群组':'切换视角，体验不同成员身份'}}</text></view><PjIcon name="arrow"/></button><text v-if="error" class="error">{{error}}</text><text class="login-note">体验数据保存在本机数据库。正式版将接入微信登录。</text></view>
  <view v-else class="login-panel"><view class="pill">微信体验版</view><text class="section-title">欢迎来到积乐圈</text><text class="muted intro">登录后创建或加入群组，一起积攒成长。</text><button class="btn primary" :disabled="busy" @click="loginWechat">{{busy?'正在登录…':'微信登录'}}</button><text v-if="error" class="error">{{error}}</text><text class="login-note">登录后可在个人资料中选择头像、填写昵称。</text></view>
 </view>
 <view v-else class="app-shell">
  <view class="sidebar">
   <view class="brand"><image src="/static/pointjoy.png" class="logo"/><view><text class="brand-name">积乐圈</text><text class="brand-en">POINTJOY</text></view></view>
   <button role="button" class="group-select" @click="open('groups')"><view class="group-mini" :class="d?.group.color||'blue'">{{d?.group.name?.slice(0,1)||'圈'}}</view><view class="group-label"><text>{{d?.group.name||'选择一个群组'}}</text><text class="small muted">{{d?roleLabel(d.membership.effectiveRole)+' · '+d.memberCount+' 位伙伴':'一起积攒小美好'}}</text></view><PjIcon name="down" :size="15"/></button>
   <view class="nav-list"><button role="button" v-for="t in tabs" :key="t.id" class="nav-item" :class="{active:tab===t.id}" @click="nav(t.id)"><PjIcon :name="t.icon"/><text>{{t.label}}</text><view v-if="tab===t.id" class="nav-dot"/></button></view>
   <view v-if="admin" class="admin-navigation"><text class="nav-caption">群组管理</text><button role="button" v-for="t in adminTabs" :key="t.id" class="nav-item" :class="{active:tab===t.id}" @click="nav(t.id)"><PjIcon :name="t.icon"/><text>{{t.label}}</text><text v-if="t.id==='orders'&&pendingOrders.length" class="nav-count">{{pendingOrders.length}}</text></button></view>
   <view class="sidebar-bottom"><view class="encouragement"><PjIcon name="star" :size="24"/><text>小小的积累，<br/>也会闪闪发光。</text></view><button role="button" class="account-button" @click="app.authMode==='demo'?open('users'):open('profile')"><view class="avatar small-avatar" :class="app.user.avatar"><image v-if="app.user.avatar?.startsWith('http')" class="avatar-image" :src="app.user.avatar" mode="aspectFill"/><text v-else>{{app.user.displayName.slice(-2)}}</text></view><view class="identity-copy"><text class="strong">{{app.user.displayName}}</text><text class="small muted">{{app.authMode==='demo'?'切换体验账号':'微信账号'}}</text></view><PjIcon name="down" :size="15"/></button></view>
  </view>
  <view class="workspace">
   <view class="topbar"><view class="breadcrumb"><text>我的空间</text><PjIcon name="chevron" :size="13"/><text>{{titles[tab]}}</text></view><button role="button" class="mobile-group" @click="open('groups')"><image src="/static/pointjoy.png" class="mobile-logo"/><text>{{d?.group.name||'选择群组'}}</text><PjIcon name="down" :size="15"/></button><view class="topbar-right"><text class="preview-dot"/><text class="small muted">{{app.authMode==='demo'?'本地体验版':'微信体验版'}}</text><button role="button" class="top-avatar avatar small-avatar" :class="app.user.avatar" @click="app.authMode==='demo'?open('users'):toast('当前已通过微信登录')"><image v-if="app.user.avatar?.startsWith('http')" class="avatar-image" :src="app.user.avatar" mode="aspectFill"/><text v-else>{{app.user.displayName.slice(-2)}}</text></button></view></view>
   <view v-if="app.loading&&!d" class="loading-content"><view class="skeleton hero-skeleton"/><view class="skeleton row-skeleton"/><view class="skeleton row-skeleton"/></view>
   <view v-else-if="app.error&&!d" class="empty-state"><PjIcon name="refresh" :size="42"/><text>{{app.error}}</text><button role="button" class="btn primary" @click="app.refresh()">重新加载</button></view>
   <view v-else-if="!d" class="empty-state"><image src="/static/gift.svg" class="empty-art"/><text class="section-title">找到你的成长小圈子</text><text class="muted">创建新群，或加入伙伴的群组。</text><view class="button-row"><button role="button" class="btn primary" @click="open('groups')">选择群组</button><button role="button" class="btn secondary" @click="open('create')">创建群组</button></view></view>
   <view v-else class="content">
    <view class="page-heading"><view><text class="eyebrow">{{tab==='home'?'A LITTLE BETTER, EVERY DAY':'POINTJOY / '+titles[tab]}}</text><text class="page-title">{{tab==='home'?'嗨，'+app.user.displayName+'，今天也在发光':titles[tab]}}</text><text class="muted heading-desc">{{tab==='home'?'把认真生活的每一刻，变成值得期待的奖励。':tab==='rewards'?'点滴积累，换一份心动。':tab==='mine'?'每一步成长，都有迹可循。':'当前群组：'+d.group.name+' · 权限仅在本群生效'}}</text></view><button role="button" v-if="admin&&tab==='home'" class="btn secondary desktop-action" @click="open('invite')"><PjIcon name="plus" :size="17"/>邀请伙伴</button><view v-if="admin&&['members','manageDaily','manageActivities','manageRewards'].includes(tab)" class="heading-actions"><button v-if="tab==='members'" class="btn secondary" @click="open('invite')">邀请成员</button><button role="button" class="btn primary" @click="open(tab==='members'?'grant':managingActivities?'newActivity':'newReward')"><PjIcon name="plus" light :size="17"/>{{tab==='members'?'发积分':managingActivities?(activityKind==='DAILY'?'发布日常':'发布活动'):'添加奖励'}}</button></view></view>
    <template v-if="tab==='home'">
     <view class="overview-grid"><view class="points-hero"><view class="hero-top"><text>我的可用积分</text><view class="hero-badge"><PjIcon name="shield" light :size="14"/><text>仅在本群使用</text></view></view><view class="balance"><text>{{fmt(d.account.balance)}}</text><text class="point-unit">积分</text></view><text class="hero-caption">每一点积累，都离心愿更近一点。</text><view class="hero-actions"><button role="button" class="hero-button" @click="nav('rewards')">去兑换奖励 <PjIcon name="arrow" :size="17"/></button><button role="button" class="hero-link" @click="nav('mine')">积分明细 <PjIcon name="chevron" light :size="14"/></button></view><view class="hero-orbit orbit-one"/><view class="hero-orbit orbit-two"/><text class="hero-star">✦</text><text class="hero-star-small">✧</text></view>
      <view class="group-card"><view class="row-between"><text class="card-label">我们的小圈子</text><button role="button" v-if="admin" @click="open('settings')" aria-label="群组设置"><PjIcon name="settings" :size="18"/></button></view><view class="group-card-title"><view class="group-mini large" :class="d.group.color">{{d.group.name.slice(0,1)}}</view><view><text class="strong group-name">{{d.group.name}}</text><text class="small muted">{{d.memberCount}} 位伙伴一起成长</text></view></view><text class="group-description">{{d.group.description||'和伙伴一起，把日常的小努力变成小美好。'}}</text><view class="group-card-bottom"><text class="role-chip">{{roleLabel(d.membership.effectiveRole)}}</text><button role="button" class="text-link" @click="open('groups')">切换群组 <PjIcon name="chevron" :size="14"/></button></view></view></view>
     <view v-if="admin" class="quick-actions"><button v-for="m in homeTools" :key="m.id" role="button" @click="nav(m.id)"><view class="quick-icon" :class="m.color"><PjIcon :name="m.icon"/></view><view><text class="strong">{{m.label}}</text><text class="small muted">{{m.hint}}</text></view><view class="quick-chevron"><PjIcon name="chevron" :size="15"/></view></button></view>
     <view class="section-header"><view><text class="section-title">值得期待的小美好</text><text class="small muted">努力的下一站，是喜欢的奖励</text></view><button role="button" class="text-link" @click="nav('rewards')">全部奖励 <PjIcon name="arrow" :size="16"/></button></view>
     <view class="reward-grid"><button role="button" v-for="r in activeRewards.slice(0,4)" :key="r.id" class="reward-card" @click="open('reward',r)"><view class="reward-art"><image :src="'/static/'+r.art+'.svg'" mode="aspectFill"/><text class="reward-type">{{r.type==='VIRTUAL'?'心愿权益':'实物好礼'}}</text></view><view class="reward-info"><text class="reward-name">{{r.name}}</text><view class="row-between"><text class="price">{{fmt(r.costPoints)}} <text>积分</text></text><text class="small muted">{{r.stockAvailable>0?'剩余 '+r.stockAvailable+' 份':'已兑完'}}</text></view></view></button><view v-if="!activeRewards.length" class="inline-empty">奖励还在准备中，{{admin?'可以到奖励管理添加第一份奖励。':'期待管理员带来惊喜。'}}</view></view>
     <view class="section-header"><text class="section-title">最近的成长足迹</text><button role="button" class="text-link" @click="nav('mine')">查看全部 <PjIcon name="arrow" :size="16"/></button></view>
     <view class="ledger-card"><view v-for="e in d.entries.slice(0,4)" :key="e.id" class="ledger-row"><view class="ledger-icon" :class="e.delta>0?'green':'peach'"><PjIcon :name="e.delta>0?'star':'gift'" :size="20"/></view><view class="ledger-copy"><text class="strong">{{e.reason}}</text><text class="small muted">{{date(e.createdAt)}} · {{e.operatorName}}</text></view><text class="delta" :class="e.delta>0?'positive':''">{{e.delta>0?'+':''}}{{e.delta}}</text></view><view v-if="!d.entries.length" class="inline-empty">还没有积分记录。你的第一份成长，值得期待。</view></view>
    </template>
    <template v-if="['daily','activities'].includes(tab)||(managingActivities&&admin)">
     <text class="hint">{{managingActivities?(activityKind==='DAILY'?'管理每天可参与的日常；完成情况请前往首页「日常审核」查看。':'管理限时活动；完成情况请前往首页「活动审核」查看。'):(activityKind==='DAILY'?'每天参与日常，提交完成后由管理员审核发放积分。':'选择活动参与，提交完成后由管理员审核发放积分。')}}</text>
     <view v-if="['daily','activities'].includes(tab)" class="activity-list-toolbar"><text class="small muted">{{tab==='daily'?'每天都有新进步':'限时挑战，及时参与'}}</text><button class="text-link" @click="openHistory">{{tab==='daily'?'日常记录':'参与记录'}} <PjIcon name="chevron" :size="14"/></button></view>
     <view v-for="t in visibleActivities" :key="t.id" class="task-card" :class="{'limited-activity':t.kind==='LIMITED'}"><view class="activity-kind-tag" :class="t.kind==='LIMITED'?'limited':'daily'">{{t.kind==='LIMITED'?'限时活动':'日常'}}</view><view class="row-between"><text class="section-title">{{t.title}}</text><text class="task-points">+{{t.points}} 积分</text></view><text class="small muted">{{t.kind==='DAILY'?'日常 · 每天 00:00 更新（北京时间）':'限时 · '+date(t.startsAt)+' — '+date(t.endsAt)}}</text><text class="task-description">{{t.description}}</text><view class="row-between"><text class="small muted">{{managingActivities?activityPhase(t):myClaim(t.id)?(['CLAIMED','REJECTED'].includes(myClaim(t.id).status)&&Date.now()>=Date.parse(myClaim(t.id).expiresAt)?'已截止':activityState(myClaim(t.id).status)):activityPhase(t)}}</text><button v-if="managingActivities&&admin&&t.status==='ACTIVE'" class="text-link" @click="confirmAction('停止参与？','已参与的成员仍可在原截止时间前提交完成。',()=>perform('/groups/'+app.gid+(t.kind==='DAILY'?'/routines/':'/events/')+t.id+'/close',{},'已停止参与'))">停止参与</button></view><text v-if="['daily','activities'].includes(tab)&&myClaim(t.id)?.reviewReason" class="hint">审核说明：{{myClaim(t.id).reviewReason}}</text><button v-if="['daily','activities'].includes(tab)&&!myClaim(t.id)&&activityAvailable(t)" class="btn primary full" :disabled="busy" @click="perform('/groups/'+app.gid+(t.kind==='DAILY'?'/routines/':'/events/')+t.id+'/claim',{},'参与成功，请在截止前提交完成')">{{t.kind==='DAILY'?'参与日常':'参与活动'}}</button><button v-else-if="['daily','activities'].includes(tab)&&myClaim(t.id)&&['CLAIMED','REJECTED'].includes(myClaim(t.id).status)&&Date.now()<Date.parse(myClaim(t.id).expiresAt)" class="btn primary full" :disabled="busy" @click="open('taskSubmit',myClaim(t.id))">{{myClaim(t.id).status==='REJECTED'?'修改并重新提交':'提交完成'}}</button></view><view v-if="!visibleActivities.length" class="inline-empty">{{managingActivities?(activityKind==='DAILY'?'点击「发布日常」，为伙伴设置每日成长目标。':'点击「发布活动」，为伙伴设置限时挑战。'):(activityKind==='DAILY'?'还没有日常，等待管理员发布。':'还没有活动，等待管理员发布。')}}</view>
    </template>
    <template v-if="tab==='rewards'"><view class="filter-bar"><view class="segmented"><button role="button" v-for="f in [{id:'ALL',label:'全部奖励'},{id:'VIRTUAL',label:'心愿权益'},{id:'PHYSICAL',label:'实物好礼'}]" :key="f.id" :class="{selected:filter===f.id}" @click="filter=f.id">{{f.label}}</button></view><text class="balance-small">可用积分 <text>{{fmt(d.account.balance)}}</text></text></view><view class="reward-grid shop-grid"><button role="button" v-for="r in activeRewards" :key="r.id" class="reward-card" @click="open('reward',r)"><view class="reward-art"><image :src="'/static/'+r.art+'.svg'" mode="aspectFill"/><text class="reward-type">{{r.type==='VIRTUAL'?'心愿权益':'实物好礼'}}</text></view><view class="reward-info"><text class="reward-name">{{r.name}}</text><text class="reward-description">{{r.description}}</text><view class="row-between"><text class="price">{{fmt(r.costPoints)}} <text>积分</text></text><text class="small muted">剩余 {{r.stockAvailable}} 份</text></view><view class="exchange-label" :class="{unavailable:r.stockAvailable<1||d.account.balance<r.costPoints}">{{r.stockAvailable<1?'已兑完':d.account.balance<r.costPoints?'再攒 '+(r.costPoints-d.account.balance)+' 分':'兑换这份小美好'}}<PjIcon name="arrow" :size="16"/></view></view></button><view v-if="!activeRewards.length" class="inline-empty">这个分类暂时没有上架奖励。</view></view></template>
    <template v-if="tab==='mine'"><view class="my-summary" @click="open('profile')"><view class="avatar" :class="app.user.avatar"><image v-if="app.user.avatar?.startsWith('http')" class="avatar-image" :src="app.user.avatar" mode="aspectFill"/><text v-else>{{app.user.displayName.slice(-2)}}</text></view><view class="grow"><text class="section-title">{{app.user.displayName}}</text><text class="small muted">{{d.group.name}} · {{roleLabel(d.membership.effectiveRole)}}</text></view><view class="summary-number"><text>{{fmt(d.account.balance)}}</text><text class="small muted">可用积分</text></view><view class="summary-number hide-small"><text>{{fmt(income)}}</text><text class="small muted">近期入账</text></view></view><view v-if="admin" class="edit-tools"><button v-for="t in editTools" :key="t.id" role="button" @click="nav(t.id)"><PjIcon :name="t.icon"/><text>{{t.label}}</text></button></view><view class="section-header"><text class="section-title">我的兑换</text><text class="small muted">{{myOrders.length}} 份小美好</text></view><view class="order-grid"><button role="button" v-for="o in myOrders" :key="o.id" class="order-card" @click="open('order',o)"><image :src="'/static/'+o.rewardSnapshot.art+'.svg'" class="order-thumb" mode="aspectFill"/><view class="grow"><text class="strong">{{o.rewardSnapshot.name}}</text><text class="small muted">{{o.costPoints}} 积分 · {{date(o.createdAt)}}</text></view><text class="status" :class="o.status">{{orderName(o.status)}}</text></button><view v-if="!myOrders.length" class="inline-empty">还没有兑换记录，去挑选一份喜欢的奖励吧。</view></view><view class="section-header"><text class="section-title">积分明细</text><text class="small muted">当前群组 · 最近 100 条</text></view><view class="ledger-card"><view v-for="e in d.entries" :key="e.id" class="ledger-row"><view class="ledger-icon" :class="e.delta>0?'green':'peach'"><PjIcon :name="e.delta>0?'star':'gift'"/></view><view class="ledger-copy"><text class="strong">{{e.reason}}</text><text class="small muted">{{date(e.createdAt)}} · 余额 {{e.balanceAfter}}</text></view><text class="delta" :class="e.delta>0?'positive':''">{{e.delta>0?'+':''}}{{e.delta}}</text></view><view v-if="!d.entries.length" class="inline-empty">第一笔积分，正在路上。</view></view></template>
    <template v-if="tab==='members'&&admin"><view v-if="d.applications.length" class="application-panel"><text class="section-title">新伙伴想加入</text><view v-for="a in d.applications" :key="a.id" class="member-row"><view class="avatar green">{{a.displayName?.slice(-2)}}</view><view class="grow"><text class="strong">{{a.displayName}}</text><text class="small muted">{{date(a.createdAt)}} 申请加入</text></view><button role="button" class="btn secondary compact" :disabled="busy" @click="decision(a,'REJECT')">拒绝</button><button role="button" class="btn primary compact" :disabled="busy" @click="decision(a,'APPROVE')">同意</button></view></view><view class="section-header"><text class="section-title">群内成员 · {{d.memberCount}}</text><button role="button" class="btn secondary compact" @click="open('invite')"><PjIcon name="plus" :size="15"/>邀请伙伴</button></view><view class="ledger-card"><button role="button" v-for="m in d.members" :key="m.id" class="member-row" @click="open('member',m)"><view class="avatar" :class="m.avatar"><image v-if="m.avatar?.startsWith('http')" class="avatar-image" :src="m.avatar" mode="aspectFill"/><text v-else>{{m.displayName.slice(-2)}}</text></view><view class="grow"><text class="strong">{{m.displayName}} <text v-if="m.id===d.membership.id" class="muted small">（我）</text></text><text class="small muted">{{roleLabel(m.effectiveRole)}}</text></view><text class="member-balance">{{fmt(m.account?.balance)}} <text class="small muted">积分</text></text><PjIcon name="chevron" :size="17"/></button></view></template>
    <template v-if="tab==='manageRewards'&&admin"><view class="manage-list"><view v-for="r in d.rewards" :key="r.id" class="manage-reward"><image :src="'/static/'+r.art+'.svg'" class="order-thumb" mode="aspectFill"/><view class="grow"><text class="strong">{{r.name}}</text><text class="small muted">{{r.costPoints}} 积分 · 库存 {{r.stockAvailable}}</text></view><text class="status" :class="r.status">{{rewardStatus(r.status)}}</text><view class="manage-buttons"><button role="button" class="btn secondary compact" @click="open('editReward',r)">编辑</button><button role="button" class="btn secondary compact" @click="open('stock',r)">库存</button><button role="button" class="btn secondary compact" :disabled="busy" @click="toggleReward(r)">{{r.status==='ACTIVE'?'下架':'上架'}}</button></view></view><view v-if="!d.rewards.length" class="inline-empty">添加一份奖励，为伙伴创造期待。</view></view></template>
    <template v-if="tab==='orders'&&admin"><view class="section-header"><text class="section-title">群内兑换记录</text><text class="small muted">{{pendingOrders.length}} 份待领取 · 最近 100 条</text></view><view class="order-grid"><button role="button" v-for="o in d.orders" :key="o.id" class="order-card" @click="open('order',o)"><image :src="'/static/'+o.rewardSnapshot.art+'.svg'" class="order-thumb" mode="aspectFill"/><view class="grow"><text class="strong">{{o.rewardSnapshot.name}}</text><text class="small muted">{{o.memberName}} · {{o.costPoints}} 积分</text><text class="small muted">{{date(o.createdAt)}}</text></view><text class="status" :class="o.status">{{orderName(o.status)}}</text></button><view v-if="!d.orders.length" class="inline-empty">暂无兑换订单。</view></view></template>
    <template v-if="tab==='activity'&&admin"><view class="ledger-card"><view v-for="a in d.audits" :key="a.id" class="ledger-row"><view class="ledger-icon blue"><PjIcon name="list"/></view><view class="ledger-copy"><text class="strong">{{a.operatorName}} · {{auditName(a.action)}}</text><text class="small muted">{{a.reason||'群组管理操作'}} · {{date(a.createdAt)}}</text></view></view><view v-if="!d.audits.length" class="inline-empty">管理操作会留在这里，随时可以回看。</view></view></template>
    <text v-if="error&&!modal" class="error inline-error">{{error}}</text>
    <view class="page-footer"><text>POINTJOY</text><text>让每一份努力，都有奖励。</text></view>
   </view>
   <view class="mobile-nav"><button role="button" v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="nav(t.id)"><PjIcon :name="t.icon" :size="22"/><text>{{t.id==='home'?'群组':t.id==='daily'?'日常':t.id==='activities'?'活动':t.id==='rewards'?'奖励':'我的'}}</text></button></view>
  </view>
 </view>
 <view v-if="modal" class="modal-overlay" @click="close"><view class="dialog" :class="{'wide-dialog':modal==='groups'}" @click.stop><view class="dialog-header"><view><text class="dialog-title">{{modalTitle}}</text><text v-if="!['groups','create','join','users','recovery','profile'].includes(modal)&&d" class="small muted">{{d.group.name}}</text></view><button role="button" class="close-button" @click="close" aria-label="关闭"><PjIcon name="close"/></button></view><scroll-view scroll-y class="dialog-body">
  <template v-if="modal==='newActivity'"><template v-if="form.kind==='LIMITED'"><text class="field-label">开始时间（北京时间）</text><view class="two-fields"><picker mode="date" :value="form.startDate" @change="periodField('startDate',$event)"><view class="input">{{form.startDate}}</view></picker><picker mode="time" :value="form.startTime" @change="periodField('startTime',$event)"><view class="input">{{form.startTime}}</view></picker></view><text class="field-label">结束时间（北京时间）</text><view class="two-fields"><picker mode="date" :value="form.endDate" @change="periodField('endDate',$event)"><view class="input">{{form.endDate}}</view></picker><picker mode="time" :value="form.endTime" @change="periodField('endTime',$event)"><view class="input">{{form.endTime}}</view></picker></view></template><text class="field-label">{{form.kind==='DAILY'?'日常名称':'活动名称'}}</text><input v-model="form.title" class="input" maxlength="60" placeholder="例如：坚持阅读 30 分钟"/><text class="field-label">完成要求</text><textarea v-model="form.description" class="input textarea" maxlength="2000" placeholder="说明完成标准，方便成员提交和管理员审核"/><text class="field-label">奖励积分</text><input v-model="form.points" type="number" class="input"/><text class="hint">{{form.kind==='DAILY'?'每天可参与一次，北京时间 00:00 更新。发布后奖励积分固定。':'仅在起止时间内参与和提交。发布后奖励积分固定。'}}</text></template>
  <template v-if="modal==='taskSubmit'"><text class="strong">{{activityTitle(selected.activityId)}}</text><text class="field-label">完成说明</text><textarea v-model="form.submission" class="input textarea" maxlength="1000" placeholder="描述你完成了什么，供管理员审核"/></template>
  <template v-if="modal==='taskReview'"><text class="strong">{{selected.memberName}} · {{activityTitle(selected.activityId)}}</text><text class="task-description">{{selected.submission}}</text><view class="segmented"><button :class="{selected:form.decision==='APPROVE'}" @click="form.decision='APPROVE'">通过并发积分</button><button :class="{selected:form.decision==='REJECT'}" @click="form.decision='REJECT'">驳回修改</button></view><text class="field-label">审核说明{{form.decision==='REJECT'?'（必填）':'（选填）'}}</text><textarea v-model="form.reason" class="input textarea" maxlength="200" placeholder="填写反馈，帮助成员完成活动"/></template>
  <template v-if="modal==='profile'"><text class="hint">头像和昵称会展示给同群伙伴，可随时修改。</text><button class="profile-avatar" open-type="chooseAvatar" :disabled="busy||!!pending" @chooseavatar="chooseAvatar"><image v-if="app.user.avatar.startsWith('http')" :src="app.user.avatar" mode="aspectFill"/><text v-else>{{app.user.displayName.slice(-2)}}</text></button><text class="hint centered">点击头像，选择微信头像或照片</text><text class="field-label">昵称</text><input type="nickname" class="input" :value="form.displayName" @input="nicknameChanged($event)" @blur="nicknameChanged($event)" maxlength="24" placeholder="填写昵称，或使用微信昵称"/><text class="hint">点击输入框，可选择键盘上方的微信昵称。</text></template>
  <template v-if="modal==='users'"><text class="hint">演示身份使用各自的账号和群组权限。</text><button role="button" v-for="u in app.users" :key="u.id" class="identity" :disabled="busy" @click="login(u)"><view class="avatar" :class="u.avatar"><image v-if="u.avatar?.startsWith('http')" class="avatar-image" :src="u.avatar" mode="aspectFill"/><text v-else>{{u.displayName.slice(-2)}}</text></view><view class="grow"><text class="strong">{{u.displayName}}</text><text class="small muted">{{u.id===app.user?.id?'当前体验身份':'切换到这个身份'}}</text></view><PjIcon :name="u.id===app.user?.id?'check':'chevron'"/></button></template>
  <template v-if="modal==='groups'"><text class="hint">每个群都有独立的积分、奖励和成员身份。</text><button role="button" v-for="g in app.groups" :key="g.group.id" class="group-option" :class="{chosen:app.gid===g.group.id}" @click="switchGroup(g.group.id)"><view class="group-mini large" :class="g.group.color">{{g.group.name.slice(0,1)}}</view><view class="grow"><text class="strong">{{g.group.name}}</text><text class="small muted">{{roleLabel(g.membership.effectiveRole)}} · {{g.memberCount}} 位伙伴 · {{g.account.balance}} 积分</text></view><PjIcon :name="app.gid===g.group.id?'check':'chevron'"/></button><view v-if="!app.groups.length" class="inline-empty">还没有加入的群组，创建或加入一个吧。</view><view class="button-row group-dialog-actions"><button role="button" class="btn primary" @click="open('create')"><PjIcon name="plus" light :size="18"/>创建群组</button><button role="button" class="btn secondary" @click="open('join')">输入邀请码</button></view></template>
  <template v-if="modal==='create'"><text class="hint">建一个小圈子，让彼此的努力被看见。</text><text class="field-label">群组名称</text><input v-model="form.name" class="input" maxlength="30" placeholder="例如：我们的周末成长小队"/><text class="field-label">群组简介</text><textarea v-model="form.description" class="input textarea" maxlength="200" placeholder="想和伙伴一起完成什么？"/><text class="field-label">群组颜色</text><view class="color-options"><button role="button" v-for="c in ['blue','green','peach','purple']" :key="c" :class="c" @click="form.color=c"><PjIcon v-if="form.color===c" name="check"/></button></view></template>
  <template v-if="modal==='join'"><text class="hint">向群管理员获取邀请码，申请加入他们的小圈子。</text><text class="field-label">邀请码</text><input v-model="form.code" class="input code-input" maxlength="32" placeholder="输入 12 位邀请码"/><view v-if="myApplications.length" class="application-status"><text class="field-label">我的申请</text><view v-for="a in myApplications.slice(0,5)" :key="a.id" class="row-between"><text class="small muted">{{date(a.createdAt)}}</text><text class="small">{{a.status==='PENDING'?'等待审核':a.status==='APPROVED'?'已通过':'未通过'}}</text></view></view></template>
  <template v-if="modal==='invite'"><view class="invite-art"><PjIcon name="users" :size="40"/></view><text class="invite-title">快乐的事，和伙伴一起</text><text class="hint centered">分享邀请码，伙伴提交申请后，<br/>你可以在成员管理中同意加入。</text><view v-if="invite" class="invite-code"><text>{{invite}}</text><text class="small muted">7 天内有效 · 最多 100 个申请</text></view><text v-else class="hint centered">点击下方按钮，生成本群专属邀请码。</text></template>
  <template v-if="modal==='grant'"><text class="field-label">选择成员</text><view class="member-chips"><button role="button" v-for="m in availableMembers" :key="m.id" :class="{selected:form.memberId===m.id}" @click="form.memberId=m.id">{{m.displayName}}</button></view><text v-if="!availableMembers.length" class="hint">请先邀请其他伙伴加入，不能给自己发分。</text><text class="field-label">操作类型</text><view class="segmented"><button role="button" :class="{selected:form.type==='GRANT'}" @click="form.type='GRANT'">发放积分</button><button role="button" :class="{selected:form.type==='ADJUSTMENT'}" @click="form.type='ADJUSTMENT'">调整积分</button></view><text class="field-label">{{form.type==='GRANT'?'奖励积分':'变动积分（扣分请填负数）'}}</text><input v-model="form.delta" class="input" type="text" placeholder="输入整数"/><view class="amount-chips"><button role="button" v-for="n in [5,10,20,50]" :key="n" @click="form.delta=n">+{{n}}</button></view><text class="field-label">这份积分，因为什么？</text><textarea v-model="form.reason" class="input textarea" maxlength="200" placeholder="例如：坚持阅读 30 分钟，真棒！"/><view class="soft-note">积分将在「{{d?.group.name}}」内生效，每次操作都会留下记录。</view></template>
  <template v-if="modal==='reward'"><image :src="'/static/'+selected.art+'.svg'" class="dialog-reward-art" mode="aspectFill"/><view class="reward-dialog-title"><text class="section-title">{{selected.name}}</text><text class="price">{{selected.costPoints}} <text>积分</text></text></view><text class="hint">{{selected.description||'为自己的认真，准备一份小奖励。'}}</text><view class="detail-lines"><view><text>领取方式</text><text>{{selected.type==='VIRTUAL'?'管理员确认权益':'线下领取实物'}}</text></view><view><text>剩余份数</text><text>{{selected.stockAvailable}} 份</text></view><view><text>我的积分</text><text>{{d?.account.balance}} 积分</text></view></view><view class="soft-note">{{selected.fulfillmentInstructions}}。兑换后立即扣分，领取前可取消并全额返还。</view></template>
  <template v-if="modal==='order'"><view class="order-detail-head"><image :src="'/static/'+selected.rewardSnapshot.art+'.svg'" class="order-thumb" mode="aspectFill"/><view><text class="strong">{{selected.rewardSnapshot.name}}</text><text class="small muted">{{selected.costPoints}} 积分</text></view><text class="status" :class="selected.status">{{orderName(selected.status)}}</text></view><view class="detail-lines"><view><text>领取成员</text><text>{{selected.memberName}}</text></view><view><text>兑换时间</text><text>{{date(selected.createdAt)}}</text></view><view><text>订单编号</text><text class="tiny-code">{{selected.id.slice(0,8).toUpperCase()}}</text></view></view><view class="soft-note">{{selected.rewardSnapshot.fulfillmentInstructions}}</view><template v-if="selected.status==='PENDING'"><text class="field-label">{{admin&&selected.memberId!==d.membership.id?'交付备注或取消原因':'取消原因'}}</text><textarea v-model="form.reason" class="input textarea" maxlength="180" placeholder="确认交付时填写奖励内容；取消时说明原因"/><text v-if="selected.memberId===d.membership.id" class="hint">请联系本群其他管理员确认领取，你不能核销自己的订单。</text></template><text v-if="selected.status==='CANCELED'" class="hint">取消原因：{{selected.cancelReason}}，积分已返还。</text><text v-if="selected.status==='FULFILLED'" class="hint">已交付：{{selected.fulfillmentNote}}</text></template>
  <template v-if="modal==='newReward'||modal==='editReward'"><text class="field-label">奖励名称</text><input v-model="form.name" class="input" maxlength="50" placeholder="例如：一杯喜欢的咖啡"/><text class="field-label">奖励说明</text><textarea v-model="form.description" class="input textarea" maxlength="2000" placeholder="介绍一下这份小美好"/><template v-if="modal==='newReward'"><text class="field-label">奖励类型</text><view class="segmented"><button role="button" :class="{selected:form.type==='VIRTUAL'}" @click="form.type='VIRTUAL'">心愿权益</button><button role="button" :class="{selected:form.type==='PHYSICAL'}" @click="form.type='PHYSICAL'">实物好礼</button></view><text class="field-label">选择封面</text><view class="art-options"><button role="button" v-for="a in ['coffee','book','game','plant','gift','movie']" :key="a" :class="{selected:form.art===a}" @click="form.art=a"><image :src="'/static/'+a+'.svg'" mode="aspectFill"/></button></view></template><view class="two-fields"><view><text class="field-label">所需积分</text><input v-model="form.costPoints" class="input" type="number"/></view><view v-if="modal==='newReward'"><text class="field-label">初始库存</text><input v-model="form.initialStock" class="input" type="number"/></view></view><text class="field-label">领取说明</text><textarea v-model="form.fulfillmentInstructions" class="input textarea" maxlength="500" placeholder="联系谁、在哪里领取？"/></template>
  <template v-if="modal==='stock'"><text class="hint">{{selected.name}} · 当前可用库存 {{selected.stockAvailable}}</text><text class="field-label">库存变动（减少请填负数）</text><input v-model="form.delta" class="input" type="text"/><text class="field-label">调整原因</text><input v-model="form.reason" class="input" maxlength="200" placeholder="例如：新补充了 10 份"/></template>
  <template v-if="modal==='member'"><view class="member-detail"><view class="avatar" :class="selected.avatar"><image v-if="selected.avatar?.startsWith('http')" class="avatar-image" :src="selected.avatar" mode="aspectFill"/><text v-else>{{selected.displayName.slice(-2)}}</text></view><view class="grow"><text class="section-title">{{selected.displayName}}</text><text class="small muted">{{roleLabel(selected.effectiveRole)}} · {{selected.account?.balance}} 积分</text></view><button role="button" v-if="selected.id!==d.membership.id" class="btn primary compact" @click="open('grant',selected)">发积分</button></view><view v-if="d.membership.effectiveRole==='OWNER'&&selected.id!==d.membership.id" class="button-row"><button role="button" class="btn secondary compact" @click="changeRole">{{selected.role==='ADMIN'?'撤销管理员':'设为管理员'}}</button><button role="button" class="btn secondary compact" @click="transfer">转让群主</button></view><text class="field-label">最近积分记录</text><view v-for="e in history" :key="e.id" class="member-history"><view class="grow"><text class="strong">{{e.reason}}</text><text class="small muted">{{date(e.createdAt)}} · {{e.delta>0?'+':''}}{{e.delta}} 积分</text></view><button role="button" v-if="['GRANT','ADJUSTMENT'].includes(e.type)&&selected.id!==d.membership.id" class="text-link" :disabled="busy" @click="reverse(e)">冲正</button></view><text v-if="!history.length" class="hint">暂无积分记录</text></template>
  <template v-if="modal==='settings'"><text class="field-label">群组名称</text><input v-model="form.name" class="input" maxlength="30"/><text class="field-label">群组简介</text><textarea v-model="form.description" class="input textarea" maxlength="200"/></template>
  <template v-if="modal==='recovery'"><text class="hint">上次操作的结果尚未确认。使用原请求重新确认，可以避免重复扣分或重复创建。</text></template>
  <text v-if="error" class="error">{{error}}</text>
 </scroll-view><view v-if="!['groups','users','member'].includes(modal)" class="dialog-footer"><button role="button" v-if="pending" class="btn primary full" :disabled="busy" @click="perform(pending.path,pending.body,pending.success,pending.method)">{{busy?'正在确认…':'重试确认上次操作'}}</button><template v-else-if="modal==='order'"><view v-if="selected.status==='PENDING'" class="button-row"><button role="button" class="btn secondary grow" :disabled="busy" @click="orderAction('cancel')">取消兑换</button><button role="button" v-if="admin&&selected.memberId!==d.membership.id" class="btn primary grow" :disabled="busy" @click="orderAction('fulfill')">确认交付并核销</button></view><button role="button" v-else class="btn secondary full" @click="close">好的</button></template><button role="button" v-else-if="modal==='invite'&&invite" class="btn primary full" @click="copyInvite"><PjIcon name="copy" light :size="18"/>复制邀请码</button><button role="button" v-else-if="modal!=='recovery'" class="btn primary full" :disabled="busy||(modal==='reward'&&(selected.stockAvailable<1||d.account.balance<selected.costPoints))||(modal==='grant'&&!availableMembers.length)" @click="submit">{{busy?'正在保存…':modal==='reward'?(selected.stockAvailable<1?'奖励已兑完':d.account.balance<selected.costPoints?'积分还不够，继续加油':'确认兑换 · '+selected.costPoints+' 积分'):modal==='create'?'创建群组':modal==='join'?'申请加入':modal==='invite'?'生成邀请码':modal==='grant'?'确认积分变动':modal==='newReward'?'保存为草稿':'保存修改'}}</button></view></view></view>
 <view v-if="message" class="toast"><PjIcon name="check" light :size="18"/><text>{{message}}</text></view>
</template>

